-- 20261110000002_reference_tables.sql
-- Read-only reference data. Written only by service_role / migrations / seeds
-- (supabase/seed/*.sql is generated by packages/core).

create table if not exists public.nutrients (
  code            text primary key check (code ~ '^[A-Z][A-Z0-9_]*$'),
  name            text not null,
  short_name      text,
  unit            text not null,
  nutrient_group  text not null,
  fdc_id          int,
  fdc_alt_ids     int[] default '{}',
  off_key         text,
  sort_order      int not null default 0,
  computed        boolean not null default false,  -- derived (e.g. net carbs), never imported
  limit_nutrient  boolean not null default false,  -- "less is better" (sodium, sat. fat, ...)
  highlight       boolean not null default false   -- shown in the compact dashboard
);

comment on table public.nutrients is
  'Nutrient catalogue. foods.nutrients / daily_totals.nutrients are keyed by nutrients.code (no FK: jsonb).';

create index if not exists nutrients_fdc_id_idx on public.nutrients (fdc_id) where fdc_id is not null;

-- Dietary Reference Intakes. NULL age_min / age_max = unbounded.
-- Intentionally no unique constraint: seeds should `delete from public.dri_values`
-- (or truncate) before re-inserting.
create table if not exists public.dri_values (
  id            integer generated by default as identity primary key,
  nutrient_code text not null references public.nutrients (code) on update cascade on delete cascade,
  sex           text not null default 'any' check (sex in ('male', 'female', 'any')),
  age_min       int check (age_min is null or age_min >= 0),
  age_max       int check (age_max is null or age_max >= 0),
  life_stage    text not null default 'normal' check (life_stage in ('normal', 'pregnant', 'lactating')),
  rda           numeric,
  ai            numeric,
  ul            numeric,
  ul_scope      text,   -- 'all' | 'supplement_only' | 'synthetic_only' | 'preformed_only' (limit applies only to that form)
  cdrr          numeric, -- chronic disease risk reduction intake
  constraint dri_values_age_range check (age_min is null or age_max is null or age_min <= age_max)
);

create index if not exists dri_values_lookup_idx on public.dri_values (nutrient_code, sex, life_stage);

create table if not exists public.exercise_activities (
  code      text primary key,
  name      text not null,
  met       numeric not null check (met > 0),
  category  text
);

-- Server-controlled application settings (readable by clients, writable only by
-- service_role). jsonb value, e.g. coach_retention_days = 90.
create table if not exists public.app_settings (
  key         text primary key,
  value       jsonb not null,
  updated_at  timestamptz not null default now()
);

insert into public.app_settings (key, value)
values ('coach_retention_days', '90'::jsonb)
on conflict (key) do nothing;
